/// **What the test set is held to, at every place** — the cells of `item-set` beside its
/// row in [`HERE`]. The script takes that writer at every POSITION of a run, and holds
/// what it writes to two things the run holds: the census, and what a round has run or
/// owes. The items are [`two_clause_run`]'s — a check of `clause-a` that runs on every
/// candidate, and a hunt of `clause-b` behind [`INSIDE`]; at the opening the run holds
/// neither them nor a census, and each row there is a new item.
const HELD: &[Taken] = &[
    Taken {
        // An item judges a clause of the census: taken only while there is none.
        name: "item-set, a new item of a clause the census does not name",
        takes: AT_THE_OPENING,
        call: |rig, _, _| rig.run(&item_set(RUN), &item("prop-item").to_string()),
    },
    Taken {
        // The brief is no cell the derivation reads: corrected anywhere.
        name: "item-set, the hunt's brief corrected",
        takes: ANYWHERE,
        call: |rig, _, _| {
            let mut hunt = item("row-clause-b");
            hunt["clause"] = json!("clause-b");
            hunt["brief"] = json!("the brief, corrected");
            rig.run(&item_set(RUN), &hunt.to_string())
        },
    },
    Taken {
        // What the derivation reads stands from the hunt's first run on, and from the
        // first tested round that owes it one: until then the row is replaced whole.
        name: "item-set, the hunt's door changed",
        takes: WHILE_NOT_TESTED,
        call: |rig, _, _| {
            let mut hunt = item("row-clause-b");
            hunt["clause"] = json!("clause-b");
            hunt["doors"] = json!([EXCLUDED]);
            rig.run(&item_set(RUN), &hunt.to_string())
        },
    },
    Taken {
        // A check is owed by every tested round: the same, from the first one on.
        name: "item-set, the check's clause changed",
        takes: WHILE_NOT_TESTED,
        call: |rig, _, _| {
            let mut check = item("check-clause-a");
            check["clause"] = json!("clause-b");
            check["kind"] = json!("check");
            check["runs"] = json!("every-candidate");
            check["doors"] = json!([]);
            rig.run(&item_set(RUN), &check.to_string())
        },
    },
];

/// What a refusal of the script lists after `opens`, up to the next ` —` or the line's end.
fn listed_in(seen: &Seen, opens: &str) -> BTreeSet<String> {
    let (_, rest) = seen
        .stderr
        .split_once(opens)
        .unwrap_or_else(|| panic!("the refusal lists them after `{opens}`: {}", seen.stderr));
    rest.trim_end()
        .split(" — ")
        .next()
        .expect("a list")
        .split(", ")
        .map(str::to_owned)
        .collect()
}

fn copy_tree(from: &Path, to: &Path) {
    fs::create_dir_all(to).expect("create a directory");
    for entry in fs::read_dir(from).expect("read a directory") {
        let entry = entry.expect("an entry");
        let target = to.join(entry.file_name());
        if entry.file_type().expect("its type").is_dir() {
            copy_tree(&entry.path(), &target);
        } else {
            fs::copy(entry.path(), &target).expect("copy a file");
        }
    }
}

/// **A recorded fact is accepted only where the state asks for it** (the review's `F7` is
/// the case in hand; the repair plan's change C5). The table is the script's own —
/// `WRITERS`, `ROUND_TAKES`, `RUN_TAKES` — and this arm holds it cell by cell: EVERY
/// writer, and EVERY fact of a round's record and of the run's, driven at EVERY position
/// of [`PLACES`], each cell's expectation written by hand in the row. And the rows are
/// held to the script's own lists — its subcommands, and the facts its two fact writers
/// name — so a writer or a fact added later has a row here, or this arm is red; and the
/// script itself takes no call while its own table lacks one.
#[test]
fn every_writer_and_every_fact_is_taken_only_where_the_state_asks_for_it() {
    // The rows are the script's own lists, whole.
    let rig = Rig::new("table-lists");
    let named: BTreeSet<String> = subcommands(&rig).into_iter().collect();
    let facts_of = |args: Vec<String>, opens: &str| {
        let seen = rig.run(&args, "{}");
        seen.refused(BAD_VALUE, "facts that say nothing");
        listed_in(&seen, opens)
    };
    let round_facts = facts_of(round_set(RUN, "1"), "naming at least one of ");
    let run_facts = facts_of(run_set(RUN), "naming at least one of ");
    assert!(
        round_facts.len() >= 14 && run_facts.len() >= 8,
        "the script lists its facts: {round_facts:?} {run_facts:?}"
    );
    let rows: BTreeSet<String> = HERE.iter().map(|write| write.name.to_owned()).collect();
    let mut owed: BTreeSet<String> = named
        .iter()
        .filter(|name| {
            !READERS.contains(&name.as_str())
                && !KEEPERS.contains(&name.as_str())
                && !["round-set", "run-set"].contains(&name.as_str())
        })
        .cloned()
        .collect();
    owed.extend(round_facts.iter().map(|fact| format!("round-set {fact}")));
    owed.extend(run_facts.iter().map(|fact| format!("run-set {fact}")));
    assert_eq!(
        rows, owed,
        "the table's rows (left) are every writer and every fact the script names (right)"
    );
    assert_eq!(HERE.len(), rows.len(), "and no row stands twice");
    for write in HERE.iter().chain(NEXT).chain(HELD) {
        assert!(
            write.takes.len() == PLACES.len()
                && write.takes.chars().all(|cell| "ars".contains(cell)),
            "`{}` has a cell per place",
            write.name
        );
    }

    // The table, cell by cell: a thread per place, the place stood up once and put back
    // as it was before every write.
    let cells: usize = std::thread::scope(|threads| {
        let workers: Vec<_> = (0..PLACES.len())
            .map(|n| {
                threads.spawn(move || {
                    let rig = place(n);
                    let read = rig.state();
                    let (next, stop, begins) = PLACE_SAYS[n];
                    assert_eq!(
                        json!([read["next"], read["stop"]["why"], read["begins"]]),
                        json!([next, stop, begins]),
                        "the place `{}`: {read}",
                        PLACES[n]
                    );
                    let pristine = rig.tmp.join("pristine");
                    copy_tree(&rig.run_dir(), &pristine);
                    let here = usize::try_from(read["round"].as_u64().unwrap_or(1))
                        .expect("a round");
                    let mut driven = 0;
                    for (writes, round) in [(HERE, here), (NEXT, here + 1), (HELD, here)] {
                        for write in writes {
                            fs::remove_dir_all(rig.run_dir()).expect("clear the run");
                            copy_tree(&pristine, &rig.run_dir());
                            let before = rig.snapshot();
                            let seen = (write.call)(&rig, &read, round);
                            let what = format!(
                                "`{}` for round {round} at `{}`",
                                write.name, PLACES[n]
                            );
                            match write.takes.as_bytes()[n] {
                                b'a' => {
                                    seen.must(OK, &what);
                                }
                                b's' => {
                                    seen.refused(NO_SCOPE, &what);
                                }
                                _ => {
                                    assert!(
                                        [Some(BAD_VALUE), Some(EXISTS)].contains(&seen.code),
                                        "{what}: refused as not asked for, or as written once: {seen:?}"
                                    );
                                    assert_eq!(rig.snapshot(), before, "{what}: nothing written");
                                }
                            }
                            driven += 1;
                        }
                    }
                    driven
                })
            })
            .collect();
        workers
            .into_iter()
            .map(|worker| worker.join().expect("a place's thread"))
            .sum()
    });
    assert_eq!(cells, (HERE.len() + NEXT.len() + HELD.len()) * PLACES.len());

    // COVERED BY CONSTRUCTION: a fact or a subcommand added to the script without its row
    // in the script's own table is no call the script takes — every call says so.
    for (from, to, names) in [
        (
            "ROUND_FACTS = (\"candidate\",",
            "ROUND_FACTS = (\"landed\", \"candidate\",",
            "landed",
        ),
        (
            "RUN_FACTS = (\"stop\",",
            "RUN_FACTS = (\"laps\", \"stop\",",
            "laps",
        ),
        (
            "    command(\"recover\", recover_, [])\n",
            "    command(\"recover\", recover_, [])\n    command(\"forget\", recover_, [])\n",
            "forget",
        ),
    ] {
        let other = Rig::new(&format!("table-{names}"));
        let script = other.root.join(SCRIPT);
        let text = fs::read_to_string(&script).expect("the rig's script");
        assert!(text.contains(from), "the script's own list: `{from}`");
        fs::write(&script, text.replace(from, to)).expect("add one without its row");
        for args in [state(RUN), ledger_add(RUN), run_set(RUN)] {
            let seen = other.run(&args, &row("audit-f3").to_string());
            seen.refused(FAULT, "a call of a script whose table lacks a row");
            assert!(
                seen.stderr.contains(names) && seen.stderr.contains("writer x state table"),
                "it names what has no row: {}",
                seen.stderr
            );
        }
    }
}

// ---------------------------------------------------------------------------
// 29 · vet: what a writer checks, checked again where the content becomes permanent
// ---------------------------------------------------------------------------

fn vet(run: &str, subject: Option<&str>, paths: &[&str]) -> Vec<String> {
    let mut args = vec!["vet".to_owned(), format!("--run={run}")];
    args.extend(subject.map(|subject| format!("--subject={subject}")));
    args.push("--".to_owned());
    args.extend(strings(paths));
    args
}

fn set_aside(run: &str, to: Option<&Path>, paths: &[&str]) -> Vec<String> {
    let mut args = vec!["set-aside".to_owned(), format!("--run={run}")];
    args.extend(to.map(|to| format!("--to={}", to.display())));
    args.push("--".to_owned());
    args.extend(strings(paths));
    args
}

/// What a hand can leave at a file's path that no writer of the script would have: the
/// word the writer refuses it with, the text, the needle the text carries, and whether
/// only a report is refused for it.
fn unwritable(rig: &Rig) -> Vec<(&'static str, String, String, bool)> {
    let home = format!("{}/probe", rig.home.display());
    vec![
        (
            "hygiene",
            format!("# a report\n\nIt met {DENY_TERM} there.\n{ENDS}\n"),
            DENY_TERM.to_owned(),
            false,
        ),
        (
            "hygiene",
            format!("# a report\n\nThe environment held {STUB_SECRET}.\n{ENDS}\n"),
            STUB_SECRET.to_owned(),
            false,
        ),
        (
            "host-path",
            format!("# a report\n\nIt ran in {home}.\n{ENDS}\n"),
            home,
            false,
        ),
        // The fence's refusal names the command it reads; what it does not name is the rest.
        (
            "fence",
            format!("# a report\n\n{INSTALL_COMMAND} --locked\n{ENDS}\n"),
            "--locked".to_owned(),
            false,
        ),
        (
            "truncated",
            "# a report\n\nIt was cut off here\n".to_owned(),
            "cut off here".to_owned(),
            true,
        ),
        ("bad-value", " \n\n".to_owned(), " \n\n".to_owned(), false),
    ]
}

/// **`vet` holds a file to what a writer of the script would have left at its path** — the
/// second repair plan's `P2`: a reporter has a shell, so a file at a report's path is
/// whatever its last writer left, and what a writer checks at its write is checked again by
/// one read, with the writers' own functions. Every refusal a writer has, at a report's
/// path and at a scope's; the one file of several that is refused, and no other; the
/// subject; the path; and a scanner that cannot run, which is never an answer.
#[test]
fn vet_holds_a_file_to_what_a_writer_of_the_script_would_have_left() {
    let rig = Rig::new("vet");
    rig.run(&report(RUN, "1", "audit-install", "1"), BODY)
        .must(OK, "a report");
    rig.run(
        &scope_set(RUN, "1"),
        &scope(&["jigc setup"], &[]).to_string(),
    )
    .must(OK, "the round's scope");
    let (written, by_hand, the_scope) = (
        report_path("1", "audit-install", "1"),
        report_path("1", "review-source", "1"),
        scope_path("1"),
    );
    // MUST NOT REFUSE: what the script wrote — and a report a hand wrote that is what the
    // script would have written, the public placeholders themselves among its text.
    let placeholders = format!(
        "# a report\n\nIt ran in <scratch>/probe, in <tmp>/x and in ~/y, from `.`.\n{ENDS}\n"
    );
    fs::write(rig.root.join(&by_hand), &placeholders).expect("a report by hand");
    let all = [written.as_str(), by_hand.as_str(), the_scope.as_str()];
    let before = rig.snapshot();
    let seen = rig.run(&vet(RUN, Some("docs(record): a record"), &all), "");
    seen.must(OK, "what the script would have written");
    assert_eq!(
        seen.json(),
        json!({
            "check": "vet", "ok": true, "refused": [], "subject": null, "stale": [],
            "vetted": {
                &written: sha256_of(BODY),
                &by_hand: sha256_of(&placeholders),
                &the_scope: sha256_of(&rig.read(&the_scope)),
            },
        })
    );
    assert_eq!(rig.snapshot(), before, "a read: nothing written");

    // EVERY REFUSAL A WRITER HAS, at a report's path and at a scope's — and of the three
    // files the one that is refused, by where and never by what.
    let scope_text = rig.read(&the_scope);
    for (word, text, needle, reports_only) in unwritable(&rig) {
        for target in [&by_hand, &the_scope] {
            if reports_only && target == &the_scope {
                continue;
            }
            fs::write(rig.root.join(target), &text).expect("a hand's text");
            let seen = rig.run(&vet(RUN, None, &all), "");
            let what = format!("`{word}` at {target}");
            seen.must(VET_MISMATCH, &what);
            let said = seen.json();
            assert_eq!(
                json!([
                    said["ok"],
                    said["refused"][0]["path"],
                    said["refused"][0]["why"],
                    said["refused"].as_array().map(Vec::len)
                ]),
                json!([false, target, word, 1]),
                "{what}: {said}"
            );
            assert!(
                said["vetted"].get(target.as_str()).is_none()
                    && said["vetted"]
                        .as_object()
                        .is_some_and(|vetted| vetted.len() == 2),
                "{what}: the other two are vetted, and it is not: {said}"
            );
            assert!(
                needle.trim().is_empty() || !seen.stdout.contains(&needle),
                "{what}: named by where, never by what: {}",
                seen.stdout
            );
            fs::write(rig.root.join(&by_hand), &placeholders).expect("the report again");
            fs::write(rig.root.join(&the_scope), &scope_text).expect("the scope again");
        }
    }

    // THE SUBJECT: one line, no host path, scanned with the files — and a hit in it is
    // the subject's, never a file's.
    for (word, subject) in [
        ("hygiene", format!("docs(record): {DENY_TERM} is on record")),
        ("hygiene", format!("docs(record): {STUB_SECRET}")),
        (
            "host-path",
            format!("docs(record): written in {}", rig.home.display()),
        ),
        ("bad-value", "docs(record): two\nlines".to_owned()),
    ] {
        let seen = rig.run(&vet(RUN, Some(&subject), &all), "");
        seen.must(VET_MISMATCH, word);
        let said = seen.json();
        assert_eq!(
            json!([said["subject"]["why"], said["refused"]]),
            json!([word, []]),
            "a subject refused as `{word}`: {said}"
        );
    }

    // THE PATH: a file of the run, below its directory, behind no link — and beside the
    // reports, under a report's name.
    let stray = format!("completions/artifacts/{RUN}/r1/reports/test/notes.txt");
    let linked = report_path("1", "linked", "1");
    fs::write(rig.root.join(&stray), BODY).expect("a stray file");
    symlink(rig.root.join(&written), rig.root.join(&linked)).expect("a link");
    for (word, path) in [
        ("outside", "README.md"),
        ("outside", "completions/artifacts/rc24/../rc24/opening.md"),
        ("bad-id", stray.as_str()),
        ("outside", linked.as_str()),
        ("gone", report_path("1", "nobody", "1").as_str()),
    ] {
        let seen = rig.run(&vet(RUN, None, &[path]), "");
        seen.must(VET_MISMATCH, path);
        assert_eq!(
            seen.json()["refused"],
            json!([{"path": path, "why": word, "detail": seen.json()["refused"][0]["detail"]}]),
            "`{path}` is refused as `{word}`"
        );
    }

    // A SCANNER THAT CANNOT RUN IS NEVER AN ANSWER: no result on stdout, and its own status.
    std::thread::scope(|scope| {
        for (n, (why, breaker)) in SCAN_BREAKS.iter().enumerate() {
            scope.spawn(move || {
                let mut rig = Rig::new(&format!("vet-did-not-run-{n}"));
                let path = report_path("1", "audit-install", "1");
                fs::create_dir_all(rig.root.join(&path).parent().expect("a directory"))
                    .expect("the reports' directory");
                fs::write(rig.root.join(&path), BODY).expect("a report");
                breaker(&mut rig);
                let before = rig.snapshot();
                rig.run(&vet(RUN, None, &[&path]), "")
                    .refused(DID_NOT_RUN, why);
                rig.run(&set_aside(RUN, None, &[&path]), "")
                    .refused(DID_NOT_RUN, why);
                assert_eq!(rig.snapshot(), before, "{why}: nothing was moved");
            });
        }
    });

    // And `vet --range` takes a range, and nothing that could be a flag of git's.
    for (status, args) in [
        (BAD_VALUE, vec!["vet", "--range", "--", "--output=x"]),
        (BAD_VALUE, vec!["vet", "--range", "--", "fix/x", "--all"]),
        (USAGE, vec!["vet", "--range", "--run=rc24", "--", "fix/x"]),
        (USAGE, vec!["vet", "--range"]),
        (USAGE, vec!["vet", "--", "README.md"]),
    ] {
        rig.run(&strings(&args), "")
            .refused(status, &args.join(" "));
    }
}

/// **A check kept in an applied batch never outlives the report it was a check of** (the
/// plan review's `B3`): a batch holds the result of its report check, and the commit step
/// reads that result. `check-reports` says which bytes it counted, and `vet` holds the
/// batch's checks to the disk again — a report that is gone, or that holds other bytes.
#[test]
fn a_report_check_kept_in_a_batch_is_held_to_the_disk_again() {
    let rig = Rig::new("vet-stale");
    for reporter in ["preflight", "audit-install"] {
        rig.run(&report(RUN, "1", reporter, "1"), BODY)
            .must(OK, reporter);
    }
    let batch = json!([
        call(
            check_reports(RUN, "1", "1", &["preflight", "audit-install"]),
            ""
        ),
        call(ledger_add(RUN), &row("audit-f3").to_string()),
    ]);
    rig.run(&apply(RUN, None), &batch.to_string())
        .must(OK, "the batch");
    let paths = [
        report_path("1", "preflight", "1"),
        report_path("1", "audit-install", "1"),
        ledger_path(),
    ];
    let paths: Vec<&str> = paths.iter().map(String::as_str).collect();
    let seen = rig.run(&vet(RUN, None, &paths), "");
    seen.must(OK, "a batch whose reports stand");
    assert_eq!(seen.json()["stale"], json!([]));

    let dir = format!("completions/artifacts/{RUN}/r1/reports/test");
    // Other bytes — a text a writer would have left, so nothing but the check refuses it.
    fs::write(
        rig.root.join(paths[1]),
        format!("# a report\n\nRewritten.\n{ENDS}\n"),
    )
    .expect("rewrite a report");
    let seen = rig.run(&vet(RUN, None, &paths), "");
    seen.must(VET_MISMATCH, "a report changed since its check");
    assert_eq!(
        json!([seen.json()["stale"], seen.json()["refused"]]),
        json!([[{"dir": dir, "attempt": 1, "gone": [], "changed": ["audit-install.a1.md"]}], []])
    );
    // Gone.
    fs::remove_file(rig.root.join(paths[1])).expect("delete a report");
    let seen = rig.run(&vet(RUN, None, &paths[..1]), "");
    seen.must(VET_MISMATCH, "a report gone since its check");
    assert_eq!(
        seen.json()["stale"],
        json!([{"dir": dir, "attempt": 1, "gone": ["audit-install.a1.md"], "changed": []}])
    );
    // Once the batch is taken back there is no check left to be stale.
    rig.run(&keeper("discard", RUN), "").must(OK, "discard");
    rig.run(&vet(RUN, None, &paths[..1]), "")
        .must(OK, "no batch, no check");
}

/// **A file that is no report leaves the tree — and nothing else does**: `set-aside` vets
/// the written-once files it is handed and moves each that `vet` refuses out of the
/// repository. What passes stays; a table is never set aside; and where it goes is outside
/// the repository, or the call is refused.
#[test]
fn set_aside_moves_what_is_no_report_out_of_the_repository_and_nothing_else() {
    let rig = Rig::new("set-aside");
    rig.run(&report(RUN, "1", "audit-install", "1"), BODY)
        .must(OK, "a report");
    rig.run(
        &scope_set(RUN, "1"),
        &scope(&["jigc setup"], &[]).to_string(),
    )
    .must(OK, "the round's scope");
    rig.seed_rows(&["audit-f3"]);
    let (kept, bad, the_scope) = (
        report_path("1", "audit-install", "1"),
        report_path("1", "review-source", "1"),
        scope_path("1"),
    );
    let text = format!("# a report\n\nIt met {DENY_TERM} there.\n{ENDS}\n");
    let aside = rig.dir.path().join("aside");

    // Only a file that is written once; only to a directory outside the repository.
    fs::write(rig.root.join(&bad), &text).expect("a hand's report");
    let before = rig.snapshot();
    for (what, args) in [
        ("a table", set_aside(RUN, Some(&aside), &[&ledger_path()])),
        (
            "a directory inside the repository",
            set_aside(RUN, Some(&rig.root.join("aside")), &[&bad]),
        ),
        (
            "a relative directory",
            set_aside(RUN, Some(Path::new("aside")), &[&bad]),
        ),
    ] {
        rig.run(&args, "").refused(BAD_VALUE, what);
        assert_eq!(rig.snapshot(), before, "{what}: nothing was moved");
    }

    // What `vet` refuses is moved, under its path; what it takes stays where it is.
    let seen = rig.run(
        &set_aside(RUN, Some(&aside), &[&kept, &bad, &the_scope]),
        "",
    );
    seen.must(OK, "one of three is no report");
    let moved = aside.join("r1__reports__test__review-source.a1.md");
    assert_eq!(
        seen.json(),
        json!({
            "aside": [{"path": bad, "why": "hygiene", "detail": seen.json()["aside"][0]["detail"],
                       "to": moved.display().to_string()}],
            "vetted": {&kept: sha256_of(BODY), &the_scope: sha256_of(&rig.read(&the_scope))},
        })
    );
    assert!(
        !seen.stdout.contains(DENY_TERM),
        "by where: {}",
        seen.stdout
    );
    assert_eq!(fs::read_to_string(&moved).expect("the moved file"), text);
    assert!(!rig.root.join(&bad).exists() && rig.root.join(&kept).is_file());
    // A second file of that name does not replace the first.
    fs::write(rig.root.join(&bad), "cut off\n").expect("a hand's report, again");
    let seen = rig.run(&set_aside(RUN, Some(&aside), &[&bad]), "");
    assert_eq!(
        json!([
            seen.json()["aside"][0]["why"],
            seen.json()["aside"][0]["to"]
        ]),
        json!(["truncated", format!("{}.1", moved.display())])
    );
    assert_eq!(fs::read_to_string(&moved).expect("the first stays"), text);

    // With no directory named one is minted — outside the repository, under the temp
    // directory — and a link at a report's path leaves as the link it is.
    symlink(rig.root.join(&kept), rig.root.join(&bad)).expect("a link at a report's path");
    let seen = rig.run(&set_aside(RUN, None, &[&bad]), "");
    seen.must(OK, "a link");
    let to = PathBuf::from(
        seen.json()["aside"][0]["to"]
            .as_str()
            .expect("where it went"),
    );
    assert_eq!(seen.json()["aside"][0]["why"], "outside");
    assert!(
        to.starts_with(&rig.tmp) && to.is_symlink() && !rig.root.join(&bad).is_symlink(),
        "the link was moved to a minted directory: {}",
        to.display()
    );
    assert_eq!(rig.read(&kept), BODY, "and what it pointed at is untouched");
}

// ---------------------------------------------------------------------------
// 30 · The derivation's inputs are held where they are written
// ---------------------------------------------------------------------------

/// A run that is ready — it stops at its bound, and its census is `clauses` — with no item
/// of the test set yet.
fn census_run(label: &str, clauses: &[&str]) -> Rig {
    let rig = Rig::new(label);
    rig.run(
        &run_set(RUN),
        &format!(r#"{{{BOUNDED}, {RELEASE}, "clauses": {}}}"#, json!(clauses)),
    )
    .must(OK, "the run's facts, and its census");
    rig
}

/// The candidate's gate as an item: a deterministic check of `no-lost-files`, run on every
/// candidate, that names no door.
fn gate_item() -> Value {
    let mut gate = item("gate");
    gate["kind"] = json!("check");
    gate["runs"] = json!("every-candidate");
    gate["doors"] = json!([]);
    gate
}

/// [`item`] under the id `review-setup`, with one cell of its row changed.
fn review_setup(cell: &str, value: Value) -> Value {
    let mut review = item("review-setup");
    review[cell] = value;
    review
}

/// `(next, forbids_close)` of a state document.
fn asks(read: &Value) -> Value {
    json!([read["next"], read["forbids_close"]])
}

/// **An item judges a clause of the census** (the re-review's `R5`; the second repair
/// plan's `P5`). The clause is typed twice at an opening — in the census, and in every row
/// of the test set — and the derivation walks the census: an item whose clause the census
/// does not name judged nothing, its void run was ignored, and the run answered `close`
/// over an instrument that never ran to its end. So the two are held to each other WHERE
/// EITHER IS WRITTEN, in both orders of writing — and a test set a hand bent afterwards is
/// not read.
#[test]
fn an_item_judges_a_clause_of_the_census_in_both_orders_of_writing() {
    let void = json!([{"clause": "no-lost-files", "status": "void"}]);
    let misspelt = review_setup("clause", json!("no-lost-file"));

    // The census first, and one letter missing in the second item's clause: `R5`'s block.
    let rig = census_run("census-first", &["no-lost-files"]);
    let before = rig.snapshot();
    let seen = rig.run(
        &item_set(RUN),
        &json!([gate_item(), misspelt.clone()]).to_string(),
    );
    seen.refused(BAD_VALUE, "an item of a clause the census does not name");
    assert!(
        seen.stderr.contains("review-setup")
            && seen.stderr.contains("no-lost-file,")
            && seen.stderr.contains("census"),
        "it names the item, its clause and the census: {}",
        seen.stderr
    );
    assert_eq!(
        rig.snapshot(),
        before,
        "nothing of the call is written — the gate's row neither"
    );
    // The control: the same two rows, the clause spelled as the census has it — and the
    // round of `R5`, which closed, asks for the void item's re-run.
    rig.run(
        &item_set(RUN),
        &json!([gate_item(), item("review-setup")]).to_string(),
    )
    .must(OK, "the same rows, each of a clause of the census");
    stage(
        &rig,
        1,
        &scope(&[INSIDE], &[EXCLUDED]),
        &[("gate", "green"), ("review-setup", "void")],
    );
    let read = rig.state();
    assert_eq!(asks(&read), json!(["retest", void]), "{read}");

    // The test set first: there is no census to hold a clause to yet, so the row is taken —
    // and the census that does not name its clause is what is refused, whole.
    let rig = Rig::new("items-first");
    rig.run(
        &item_set(RUN),
        &json!([gate_item(), misspelt.clone()]).to_string(),
    )
    .must(OK, "the test set, before any census");
    let census = format!(r#"{{{BOUNDED}, {RELEASE}, "clauses": ["no-lost-files"]}}"#);
    let before = rig.snapshot();
    let seen = rig.run(&run_set(RUN), &census);
    seen.refused(
        BAD_VALUE,
        "a census that does not name a clause an item judges",
    );
    assert!(
        seen.stderr.contains("review-setup") && seen.stderr.contains("no-lost-file,"),
        "it names the item and its clause: {}",
        seen.stderr
    );
    assert_eq!(
        rig.snapshot(),
        before,
        "none of the call's facts is written: a census is written once"
    );
    // The same two writes as the calls of one batch, in that order.
    let batched = Rig::new("items-first-batch");
    let batch = json!([
        call(
            item_set(RUN),
            &json!([gate_item(), misspelt.clone()]).to_string()
        ),
        call(run_set(RUN), &census),
    ]);
    let before = batched.snapshot();
    batched
        .run(&apply(RUN, None), &batch.to_string())
        .refused(BAD_VALUE, "the two writes as one batch");
    assert_eq!(
        batched.snapshot(),
        before,
        "nothing of the batch is written"
    );
    // The way out, which exists: the row has no run and no round owes it, so it is
    // replaced whole — and then the census is taken, and the run is ready.
    rig.run(&item_set(RUN), &item("review-setup").to_string())
        .must(OK, "the row, its clause corrected");
    rig.run(&run_set(RUN), &census)
        .must(OK, "the census, once every item judges a clause of it");
    let read = rig.state();
    assert_eq!(
        json!([read["not_ready"], read["next"]]),
        json!([[], "test"]),
        "{read}"
    );

    // A test set a hand bent afterwards is not read — by the state, or by a writer that
    // asks it: the derivation never passes over a row in silence. The hand is a consistent
    // one — it takes the item out of the clause table too, so the view is exactly what a
    // derivation that skipped the row would give, and the view's own check has nothing
    // to say.
    let bend = |rel: String, from: &str, to: &str| {
        let path = rig.root.join(rel);
        let text = fs::read_to_string(&path).expect("a table of the run");
        let bent = text.replacen(from, to, 1);
        assert_ne!(bent, text, "`{from}` is there to bend");
        fs::write(&path, bent).expect("bend a table by hand");
    };
    bend(
        test_set_path(),
        "| `review-row` | `no-lost-files` |",
        "| `review-row` | `no-lost-file` |",
    );
    bend(
        clauses_path(),
        "<br>`review-setup` — not selected by any tested round: it owes nothing",
        "",
    );
    for (what, seen) in [
        ("the state", rig.run(&state(RUN), "")),
        (
            "a writer of the test set",
            rig.run(&item_set(RUN), &item("review-show").to_string()),
        ),
    ] {
        seen.refused(CORRUPT, what);
        assert!(
            seen.stderr.contains("review-setup") && seen.stderr.contains("no-lost-file,"),
            "{what}: it names the item and its clause: {}",
            seen.stderr
        );
    }
}

/// **An item a round has run, or owes a run of, keeps what the derivation reads** (the
/// re-review's `R6`; the plan's `P5`). `item-set` replaced a row whole at any time: a
/// corrected brief whose door gained one space left the item selected by no round, its
/// void run stopped judging, and `retest` became `close`. Of an item's row the derivation
/// reads four cells — its clause, when it runs, its doors, its registries — and from the
/// first run on record, or the first tested round whose scope selects the item, those
/// four stand. What is still taken says what the legitimate ways are: the brief and the
/// kind are corrected at any time; an item nothing has run and nothing owes is replaced
/// whole; and an instrument that covers something else is a new item under its own id.
#[test]
fn an_item_a_round_has_run_or_owes_keeps_what_the_derivation_reads() {
    let void = json!([{"clause": "no-lost-files", "status": "void"}]);
    let rig = census_run("kept", &["no-lost-files", "no-regression"]);
    let mut regression = gate_item();
    regression["item"] = json!("regression-set");
    regression["clause"] = json!("no-regression");
    let mut show = item("review-show");
    show["doors"] = json!([EXCLUDED]);
    rig.run(
        &item_set(RUN),
        &json!([gate_item(), regression, item("review-setup"), show]).to_string(),
    )
    .must(OK, "the test set");
    stage(
        &rig,
        1,
        &scope(&[INSIDE], &[EXCLUDED]),
        &[
            ("gate", "green"),
            ("regression-set", "green"),
            ("review-setup", "void"),
        ],
    );
    let read = rig.state();
    assert_eq!(asks(&read), json!(["retest", void]), "{read}");

    // `R6`'s own write: the brief corrected, and the door's text with one space more.
    type Bend = (&'static str, &'static str, fn() -> Value);
    let bends: &[Bend] = &[
        ("doors", "the door's text, one space more", || {
            let mut bent = review_setup("doors", json!(["jigc  setup"]));
            bent["brief"] = json!("a corrected brief");
            bent
        }),
        ("doors", "one door more", || {
            review_setup("doors", json!([INSIDE, EXCLUDED]))
        }),
        ("clause", "another clause of the census", || {
            review_setup("clause", json!("no-regression"))
        }),
        ("runs", "on every candidate", || {
            review_setup("runs", json!("every-candidate"))
        }),
        ("registries", "a registry beside its door", || {
            review_setup("registries", json!(["the verb table"]))
        }),
    ];
    let before = rig.snapshot();
    for (cell, what, bent) in bends {
        let seen = rig.run(&item_set(RUN), &bent().to_string());
        seen.refused(EXISTS, what);
        assert!(
            seen.stderr.contains("review-setup")
                && seen.stderr.contains(&format!("would change its {cell} ")),
            "{what}: it names the item and the cell that differs: {}",
            seen.stderr
        );
        assert_eq!(rig.snapshot(), before, "{what}: nothing is written");
    }
    assert_eq!(asks(&rig.state()), json!(["retest", void]));

    // WHAT IS TAKEN. The brief and the kind, with the four cells as they stand: the item
    // judges as before, and its re-run is still what is asked.
    let mut corrected = review_setup("brief", json!("a corrected brief"));
    corrected["kind"] = json!("trial-arm");
    rig.run(&item_set(RUN), &corrected.to_string())
        .must(OK, "a brief and a kind, corrected");
    let read = rig.state();
    assert_eq!(asks(&read), json!(["retest", void]), "{read}");
    assert_eq!(
        json!([read["items"][2]["brief"], read["items"][2]["kind"]]),
        json!(["a corrected brief", "trial-arm"]),
        "{read}"
    );
    // An instrument that covers something else is a new item, under its own id.
    let mut wider = item("review-setup-and-show");
    wider["doors"] = json!([INSIDE, EXCLUDED]);
    rig.run(&item_set(RUN), &wider.to_string())
        .must(OK, "a new item that covers more");
    // Round 1 owes that item a run from its first row on — and a list is the set it names:
    // its doors said again in another order, beside a corrected brief, change nothing the
    // derivation reads.
    wider["doors"] = json!([EXCLUDED, INSIDE]);
    wider["brief"] = json!("the same two doors, in another order");
    rig.run(&item_set(RUN), &wider.to_string())
        .must(OK, "the same doors in another order");
    // An item nothing has run and nothing owes is replaced whole — `review-show`, whose one
    // door round 1 left out. Given the door round 1 included, round 1 owes it a run: from
    // then on its four cells stand too, though it has no result at all.
    let mut reached = item("review-show");
    reached["clause"] = json!("no-regression");
    rig.run(&item_set(RUN), &reached.to_string())
        .must(OK, "an item no round has run and none owes, replaced whole");
    let read = rig.state();
    let owed = &read["clauses"][1]["items"][1];
    assert_eq!(
        json!([owed["item"], owed["round"], owed["why"]]),
        json!(["review-show", 1, "not-run"]),
        "round 1 owes the replaced item a run: {read}"
    );
    let before = rig.snapshot();
    let mut back = item("review-show");
    back["doors"] = json!([EXCLUDED]);
    back["clause"] = json!("no-regression");
    rig.run(&item_set(RUN), &back.to_string()).refused(
        EXISTS,
        "an item a tested round owes a run of, taken out of that round's reach",
    );
    assert_eq!(rig.snapshot(), before, "nothing is written");

    // And a run on record holds the item before its round is tested: the result is of the
    // item as its row stood.
    let early = census_run("kept-early", &["no-lost-files"]);
    early
        .run(
            &item_set(RUN),
            &json!([gate_item(), item("review-setup")]).to_string(),
        )
        .must(OK, "the test set");
    early
        .run(
            &scope_set(RUN, "1"),
            &scope(&[INSIDE], &[EXCLUDED]).to_string(),
        )
        .must(OK, "round 1's scope");
    let unrun = review_setup("doors", json!([EXCLUDED]));
    early
        .run(&item_set(RUN), &unrun.to_string())
        .must(OK, "a round that is not tested owes nothing yet");
    early
        .run(&item_set(RUN), &item("review-setup").to_string())
        .must(OK, "and the row is put back");
    early
        .run(
            &result_set(RUN, "1", &candidate(1)),
            &ran("review-setup", "void").to_string(),
        )
        .must(OK, "its run, in a round that is not tested yet");
    early
        .run(&item_set(RUN), &unrun.to_string())
        .refused(EXISTS, "an item with a run on record");
    early
        .run(
            &round_set(RUN, "1"),
            &json!({"candidate": candidate(1)}).to_string(),
        )
        .must(OK, "round 1's candidate");
    assert_eq!(asks(&early.state()), json!(["retest", void]));
}

/// The plan review's `B10`, as it was driven: a run of one clause, judged by the gate and
/// by a hunt whose one door is `door`; round 1's scope includes [`INSIDE`], and the gate
/// ran green.
fn one_door_run(label: &str, door: &str) -> Rig {
    let rig = census_run(label, &["no-lost-files"]);
    rig.run(
        &item_set(RUN),
        &json!([gate_item(), review_setup("doors", json!([door]))]).to_string(),
    )
    .must(OK, "the test set");
    stage(
        &rig,
        1,
        &scope(&[INSIDE], &[EXCLUDED]),
        &[("gate", "green")],
    );
    rig
}

/// **What cannot be held is named** (the plan review's `B10`; the plan's `P5`, *Where the
/// class ends*). A round's doors are derived afresh by its scope step, so there is no list
/// an item's door could be held to — and a door mistyped by one letter reads exactly as a
/// door the round's change did not reach: the item is never selected, owes nothing, and
/// its clause is green without it. THAT IS A DECLARED BOUND, and this arm pins it: the
/// state answers `close`. What the script can do, it does: it computes, and the state
/// names, every in-scope item that no tested round's scope has selected, and every door a
/// round's scope included that no item of the test set names — so the bound's reach is
/// read at every stop, and at the close. And the names forbid nothing: an item a later
/// round leaves out, a check that runs on every candidate and a round that runs no item of
/// a clause are the scoped design, and close.
#[test]
fn an_in_scope_item_no_tested_round_selected_is_named_and_so_is_a_door_no_item_names() {
    let unnamed = |rounds: &[usize]| json!([{"door": INSIDE, "registry": "the verb table", "rounds": rounds}]);

    // `B10`'s block: one letter wrong in the hunt's door.
    let rig = one_door_run("mistyped", "jigc setpu");
    let read = rig.state();
    assert_eq!(
        json!([
            read["items"][1]["selected"],
            read["clauses"][0]["status"],
            read["next"],
            read["forbids_close"]
        ]),
        json!([false, "green", "close", []]),
        "THE BOUND: a door nothing can hold reads as a door the round did not reach: {read}"
    );
    assert_eq!(
        json!([read["never_selected"], read["uncovered"]]),
        json!([["review-setup"], unnamed(&[1])]),
        "and the state names the item nobody selected, and the door no item names: {read}"
    );
    // Its control, the door spelled as the scope has it: the hunt is owed a run.
    let control = one_door_run("spelled", INSIDE);
    let read = control.state();
    assert_eq!(
        json!([
            read["items"][1]["selected"],
            read["clauses"][0]["status"],
            read["next"],
            read["never_selected"],
            read["uncovered"]
        ]),
        json!([true, "void", "retest", [], []]),
        "{read}"
    );
    // The bound has its exit once somebody reads the name: the item has no run and no
    // round owes it, so its door is corrected — and round 1 then owes it a run.
    rig.run(&item_set(RUN), &item("review-setup").to_string())
        .must(OK, "the door, corrected");
    let read = rig.state();
    assert_eq!(
        json!([read["next"], read["never_selected"], read["uncovered"]]),
        json!(["retest", [], []]),
        "{read}"
    );

    // WHAT IS NAMED, AND WHEN. Before any round is tested no scope has selected anything:
    // every in-scope item is named, a check that runs on every candidate never is, and
    // there is no door to name.
    let rig = three_item_run("named");
    let read = rig.state();
    assert_eq!(
        json!([read["never_selected"], read["uncovered"]]),
        json!([["review-setup", "review-show"], []]),
        "{read}"
    );
    // A round that is begun and not tested has selected nothing yet — but its doors are
    // the round's, and one no item names is named from the scope on.
    rig.run(
        &scope_set(RUN, "1"),
        &json!({
            "included": [door(INSIDE), door(UNLISTED)],
            "excluded": [door(EXCLUDED)],
        })
        .to_string(),
    )
    .must(OK, "round 1's scope");
    let read = rig.state();
    assert_eq!(
        json!([read["never_selected"], read["uncovered"]]),
        json!([
            ["review-setup", "review-show"],
            [{"door": UNLISTED, "registry": "the verb table", "rounds": [1]}]
        ]),
        "an excluded door is no door of the test set, and is never named: {read}"
    );
    // A registry an item covers whole covers every door of it.
    let mut verbs = item("review-verbs");
    verbs["doors"] = json!([]);
    verbs["registries"] = json!(["the verb table"]);
    rig.run(&item_set(RUN), &verbs.to_string())
        .must(OK, "an item that covers a registry");
    assert_eq!(rig.state()["uncovered"], json!([]));

    // WHAT THE NAMES DO NOT FORBID — the scoped design, "hunt once per change, check
    // always". Round 1 selects the hunt and it runs green; its fixes land; round 2's scope
    // leaves the hunt's door out, and runs no item of `clause-b` at all.
    let rig = two_clause_run("scoped", BOUNDED);
    let both = [("check-clause-a", "green"), ("row-clause-b", "green")];
    tested_round(&rig, 1, true, &both, json!({}));
    rig.run(&round_set(RUN, "1"), r#"{"cycles": 1}"#)
        .must(OK, "round 1's fix cycle");
    tested_round(&rig, 2, false, &[("check-clause-a", "green")], json!({}));
    let read = rig.state();
    assert_eq!(
        asks(&read),
        json!(["close", []]),
        "the hunt's green of round 1 stands, and the check ran on this candidate: {read}"
    );
    assert_eq!(
        read["never_selected"],
        json!([]),
        "an item a later round leaves out was selected: it is not named: {read}"
    );
    assert_eq!(
        read["uncovered"],
        json!([{"door": EXCLUDED, "registry": "the verb table", "rounds": [2]}]),
        "round 2's one door, which no item names, is — and forbids nothing: {read}"
    );

    // A door nobody hunted behind is still that at the close: it is named for every round
    // whose test set held it, not for the latest alone.
    let rig = census_run("unhunted", &["no-lost-files"]);
    rig.run(&item_set(RUN), &gate_item().to_string())
        .must(OK, "a test set of one check");
    let inside = scope(&[INSIDE], &[EXCLUDED]);
    stage(&rig, 1, &inside, &[("gate", "green")]);
    assert_eq!(rig.state()["uncovered"], unnamed(&[1]));
    rig.run(&round_set(RUN, "1"), r#"{"cycles": 1}"#)
        .must(OK, "round 1's fix cycle");
    stage(&rig, 2, &scope(&[], &[INSIDE]), &[("gate", "green")]);
    let read = rig.state();
    assert_eq!(
        json!([read["next"], read["uncovered"]]),
        json!(["close", unnamed(&[1])]),
        "round 2 includes no door, and round 1's is named still: {read}"
    );
    rig.run(&round_set(RUN, "2"), r#"{"cycles": 1}"#)
        .must(OK, "round 2's fix cycle");
    stage(&rig, 3, &inside, &[("gate", "green")]);
    assert_eq!(rig.state()["uncovered"], unnamed(&[1, 3]));
}

// ---------------------------------------------------------------------------
// What an agent reads by key
// ---------------------------------------------------------------------------

/// The harness's `unitDoors` as it stood until the second repair plan's `K3`, word for
/// word: the doors of a round's test set a unit covers — its own doors, and those of its
/// registries; a unit that runs on every candidate and names neither covers them all.
/// SINCE `K3` THE HARNESS SELECTS NO DOOR — it reads how many a unit covers, and a unit's
/// prompt names the read below — so this transliteration is what the read is held to, and
/// the harness's own function is no longer there to be run beside it.
fn unit_doors(item: &Value, included: &[Value]) -> Vec<Value> {
    let named = |field: &str| item[field].as_array().cloned().unwrap_or_default();
    let (doors, registries) = (named("doors"), named("registries"));
    if item["runs"] == "every-candidate" && doors.is_empty() && registries.is_empty() {
        return included.to_vec();
    }
    included
        .iter()
        .filter(|door| doors.contains(&door["door"]) || registries.contains(&door["registry"]))
        .cloned()
        .collect()
}

/// **An agent reads its brief, its doors and the untriaged rows by key** (the second
/// repair plan's `K9`; [DECISIONS.md](../DECISIONS.md) → *2026-10-07 — A line holds what
/// the harness acts on*). The harness put each of them into a prompt as text it had taken
/// from the state document, which reached it through an agent's relay — and a relay does
/// not carry a sentence (the relay probe, 2026-10-07). So the script answers three reads,
/// each one line of JSON, each writing nothing, and a prompt names the read:
/// `item` — a row of the test set, whole, its brief in it; `item-doors` — the doors of a
/// round's test set the item covers, each with its registry and its derivation, selected
/// as the harness selected them until `K3` moved the selection here (its `unitDoors`,
/// transliterated above) and from THE ROUND ASKED, which for a
/// re-run is not the latest; `untriaged` — the ledger's rows whose triage is not
/// finished, whole, in the ledger's order.
#[test]
fn an_agent_reads_its_brief_its_doors_and_the_untriaged_rows_by_key() {
    let rig = census_run("reads", &["no-lost-files"]);
    let brief = "the row\u{2019}s brief \u{2014} `jigc setup` \u{2192} what it must not lose";
    let unit = |id: &str, kind: &str, runs: &str, doors: &[&str], registries: &[&str]| {
        json!({"item": id, "kind": kind, "clause": "no-lost-files", "runs": runs,
               "brief": format!("{brief} ({id})"), "doors": doors, "registries": registries})
    };
    let items = json!([
        unit("gate", "check", "every-candidate", &[], &[]),
        unit("sweep", "audit-area", "every-candidate", &[], &["codes"]),
        unit(
            "review-setup",
            "review-row",
            "in-scope",
            &["jigc setup"],
            &[]
        ),
        unit("review-codes", "review-row", "in-scope", &[], &["codes"]),
        unit(
            "review-both",
            "review-row",
            "in-scope",
            &["jigc rename"],
            &["codes"]
        ),
        unit(
            "review-typo",
            "review-row",
            "in-scope",
            &["jigc setpu"],
            &[]
        ),
    ]);
    rig.run(&item_set(RUN), &items.to_string())
        .must(OK, "the test set");
    let at = |name: &str, registry: &str| {
        json!({"door": name, "registry": registry,
               "derivation": format!("a changed symbol \u{2192} `{name}` reads it")})
    };
    let first = json!({
        "included": [at("jigc setup", "verbs"), at("jigc rename", "verbs"),
                     at("finalize.dirty", "codes"), at("finalize.clean", "codes")],
        "excluded": [at("jigc doc show", "verbs")],
    });
    rig.seed_rows(&["seeded", "second", "third"]);
    rig.run(
        &ledger_add(RUN),
        &row_at("audit-f3", "jigc setup").to_string(),
    )
    .must(OK, "a fourth row");
    rig.run(
        &ledger_set(RUN),
        &json!([{"key": "second", "disposition": "later"},
                {"key": "third", "grade": "needs-bound", "graded_by": "triage"}])
        .to_string(),
    )
    .must(
        OK,
        "a row that is ruled, and one that is the human's: neither is a triage's",
    );
    rig.run(&scope_set(RUN, "1"), &first.to_string())
        .must(OK, "round 1's scope");
    let before = rig.snapshot();
    let state = rig.state();

    // An item's row: the state's own entry, its brief whole.
    for row in state["items"].as_array().expect("the items") {
        let id = row["item"].as_str().expect("an id");
        let seen = rig.run(&read_item(RUN, id), "");
        seen.must(OK, "an item's row");
        assert_eq!(seen.json(), json!({"run": RUN, "item": row}), "`{id}`");
        assert!(
            seen.stdout.lines().count() == 1
                && row["brief"]
                    .as_str()
                    .is_some_and(|text| text.starts_with(brief)),
            "one line, and the brief as it was written: {}",
            seen.stdout
        );
    }

    // An item's doors in a round: what the harness's own selection answers.
    let selected = |round: &str, included: &Value| {
        let included = included.as_array().expect("the included doors").clone();
        let mut counts = Vec::new();
        for row in state["items"].as_array().expect("the items") {
            let id = row["item"].as_str().expect("an id");
            let seen = rig.run(&read_doors(RUN, round, id), "");
            seen.must(OK, "an item's doors");
            let expected = unit_doors(row, &included);
            assert_eq!(
                seen.json(),
                json!({"run": RUN, "round": round.parse::<u64>().expect("a round"), "item": id, "doors": expected}),
                "`{id}` in round {round}"
            );
            counts.push(expected.len());
        }
        counts
    };
    assert_eq!(
        selected("1", &state["doors"]["included"]),
        [4, 2, 1, 2, 3, 0],
        "all of them · a registry's · a door · a registry's · a door and a registry's · none, for a door mistyped"
    );

    // The untriaged rows: the ledger's own, whole, with why each is no triage's yet.
    let seen = rig.run(&keeper("untriaged", RUN), "");
    seen.must(OK, "the untriaged rows");
    let rows: Vec<&Value> = state["ledger"]
        .as_array()
        .expect("the ledger")
        .iter()
        .filter(|row| row["route"] == "triage")
        .collect();
    assert_eq!(
        seen.json(),
        json!({"run": RUN, "count": 2, "untriaged": rows}),
        "the rows the state counts as untriaged, in the ledger's order"
    );
    assert_eq!(
        state["untriaged"],
        json!([{"key": "seeded", "why": "ungraded"}, {"key": "audit-f3", "why": "ungraded"}])
    );
    for field in ["key", "why", "grade", "door", "clause", "repro"] {
        assert!(
            rows[0][field].is_string(),
            "a row says `{field}`: {}",
            rows[0]
        );
    }

    // What is asked for and is not there is refused; and a read writes nothing.
    rig.run(&read_item(RUN, "no-such-item"), "")
        .refused(NO_SUCH_ROW, "an item the test set lacks");
    rig.run(&read_doors(RUN, "1", "no-such-item"), "")
        .refused(NO_SUCH_ROW, "the doors of an item the test set lacks");
    rig.run(&read_doors(RUN, "2", "gate"), "")
        .refused(NO_SCOPE, "the doors of a round that has no scope");
    rig.run(&read_item(RUN, "Not A Slug"), "")
        .refused(BAD_ID, "an item that is no id");
    rig.run(&read_doors(RUN, "one", "gate"), "")
        .refused(BAD_ID, "a round that is no number");
    assert_eq!(rig.snapshot(), before, "the reads wrote nothing");

    // A RE-RUN NAMES THE ROUND ITS POSITION GIVES: once round 2 has a scope of its own the
    // state's doors are round 2's, and round 1's are still read by its number.
    for key in ["seeded", "third", "audit-f3"] {
        rig.run(
            &ledger_set(RUN),
            &json!({"key": key, "disposition": "later"}).to_string(),
        )
        .must(OK, "the rows are ruled");
    }
    rig.run(
        &round_set(RUN, "1"),
        &json!({"candidate": candidate(1)}).to_string(),
    )
    .must(OK, "round 1's candidate");
    // Round 1 is tested and holds no run: the step is a re-run INSIDE round 1, and what
    // the position lists as that re-run's doors is what the read answers for its round.
    let read = rig.state();
    let rerun = &read["position"]["test"]["rerun"];
    assert_eq!(
        json!([read["next"].clone(), rerun["round"].clone()]),
        json!(["retest", 1]),
        "{read}"
    );
    let again = rerun["doors"].as_array().expect("the re-run's doors");
    for entry in rerun["items"].as_array().expect("the re-run's items") {
        let id = entry["item"].as_str().expect("an id");
        let row = read["items"]
            .as_array()
            .expect("the items")
            .iter()
            .find(|row| row["item"] == id)
            .expect("the item's row");
        assert_eq!(
            rig.run(&read_doors(RUN, "1", id), "").json()["doors"],
            json!(unit_doors(row, again)),
            "`{id}`, run again in round 1"
        );
    }
    let greens: Vec<Value> = [
        "gate",
        "sweep",
        "review-setup",
        "review-codes",
        "review-both",
    ]
    .iter()
    .map(|id| ran(id, "green"))
    .collect();
    rig.run(
        &result_set(RUN, "1", &candidate(1)),
        &json!(greens).to_string(),
    )
    .must(OK, "round 1's runs");
    let second =
        json!({"included": [at("jigc rename", "verbs")], "excluded": [at("jigc setup", "verbs")]});
    rig.run(&scope_set(RUN, "2"), &second.to_string())
        .must(OK, "round 2's scope");
    assert_eq!(rig.state()["doors"]["included"], second["included"]);
    assert_eq!(selected("2", &second["included"]), [1, 0, 0, 0, 1, 0]);
    assert_eq!(selected("1", &first["included"]), [4, 2, 1, 2, 3, 0]);
    assert_eq!(
        rig.run(&keeper("untriaged", RUN), "").json(),
        json!({"run": RUN, "count": 0, "untriaged": []})
    );
}

// ---------------------------------------------------------------------------
// 31 · A writer fed from a file, and a scripted check's result
// ---------------------------------------------------------------------------

/// A call of a writer that takes its text from `file` (`--from`).
fn from_file(mut args: Vec<String>, file: &Path) -> Vec<String> {
    args.push(format!("--from={}", file.display()));
    args
}

/// **A writer takes its text from a file the caller names** (the second repair plan's
/// `K10`; the human's ruling of 2026-10-07 that no step of a stage may need his
/// permission). A here-document is a shell an agent composes, and a redirect is one more;
/// with `--from` the call that writes a report, a round's scope or a record's batch is ONE
/// plain invocation, and the text is a file the agent wrote with its file tool. What is
/// written is what the same text on stdin writes, byte for byte, stdin is not read — and a
/// batch is HELD TO THE HASH its composer names (`--sha256`): one that is not that file is
/// refused, and nothing is written.
#[test]
fn a_writer_takes_its_text_from_a_file() {
    let rig = Rig::new("from-file");
    let fed = |name: &str, text: &str| {
        let path = rig.tmp.join(name);
        fs::write(&path, text).expect("write what a writer is fed");
        path
    };

    // A report: the file, and never stdin.
    let body = format!("# a report\n\nNothing found \u{2014} \u{201c}nothing\u{201d}.\n\n{ENDS}\n");
    let file = fed("report.md", &body);
    let seen = rig.run(
        &from_file(report(RUN, "1", "audit-a", "1"), &file),
        "what stdin holds is not the report",
    );
    seen.must(OK, "a report from a file");
    assert_eq!(seen.stdout.trim(), report_path("1", "audit-a", "1"));
    rig.run(&report(RUN, "1", "audit-b", "1"), &body)
        .must(OK, "the same report on stdin");
    assert_eq!(
        rig.read(&report_path("1", "audit-a", "1")),
        rig.read(&report_path("1", "audit-b", "1")),
        "a report from a file is the report the same text on stdin leaves"
    );
    // What a writer holds its text to, it holds a file's to: a report that was cut off.
    let cut = fed("cut.md", "# a report\n\nCut off before its last li");
    let before = rig.snapshot();
    rig.run(&from_file(report(RUN, "1", "audit-c", "1"), &cut), "")
        .refused(TRUNCATED, "a file that holds a report cut off");
    // A file that is not there, and a directory: refused, and nothing written.
    for (what, path) in [
        ("a file that is not there", rig.tmp.join("no-such-file")),
        ("a directory", rig.tmp.clone()),
    ] {
        let seen = rig.run(&from_file(report(RUN, "1", "audit-c", "1"), &path), &body);
        seen.refused(BAD_VALUE, what);
        assert!(seen.stderr.contains("--from"), "{}", seen.stderr);
    }
    assert_eq!(rig.snapshot(), before, "a refused file writes nothing");

    // A round's scope.
    let doors = scope(&[INSIDE], &[EXCLUDED]).to_string();
    let seen = rig.run(
        &from_file(scope_set(RUN, "1"), &fed("scope.json", &doors)),
        "{}",
    );
    seen.must(OK, "a scope from a file");
    let other = Rig::new("from-file-stdin");
    other
        .run(&scope_set(RUN, "1"), &doors)
        .must(OK, "the same scope on stdin");
    assert_eq!(
        rig.read(&scope_path("1")),
        other.read(&scope_path("1")),
        "a scope from a file is the scope the same text on stdin leaves"
    );

    // A record's batch: from a file, HELD TO THE HASH its composer names.
    let batch = format!(
        "{}\n",
        json!([call(ledger_add(RUN), &row("audit-f4").to_string())])
    );
    let file = fed("batch.json", &batch);
    let held_to = |hash: &str| {
        let mut args = from_file(apply(RUN, None), &file);
        args.push(format!("--sha256={hash}"));
        args
    };
    let before = rig.snapshot();
    let wrong = rig.run(&held_to(&sha256('0')), "[]");
    wrong.refused(
        BAD_VALUE,
        "a batch that is not the file its composer hashed",
    );
    assert!(
        wrong.stderr.contains(&sha256_of(&batch)) && wrong.stderr.contains("--sha256"),
        "the refusal says which hash the file has: {}",
        wrong.stderr
    );
    // A file that was altered on its way: one byte.
    fs::write(&file, batch.replace("audit-f4", "audit-f5")).expect("alter the batch");
    rig.run(&held_to(&sha256_of(&batch)), "")
        .refused(BAD_VALUE, "a batch one byte of which changed");
    fs::write(&file, &batch).expect("the batch again");
    // A batch from a file names its hash, and a hash names a file.
    rig.run(&from_file(apply(RUN, None), &file), "")
        .refused(USAGE, "a batch from a file, and no hash");
    let mut alone = apply(RUN, None);
    alone.push(format!("--sha256={}", sha256_of(&batch)));
    rig.run(&alone, &batch)
        .refused(USAGE, "a hash, and no file it is the hash of");
    assert_eq!(rig.snapshot(), before, "a refused batch writes nothing");
    let applied = rig.run(&held_to(&sha256_of(&batch)), "what stdin holds is no batch");
    applied.must(OK, "the batch, from the file its hash names");
    assert_eq!(applied.json()["applied"], 1);
    assert_eq!(rig.state()["ledger"][0]["key"], "audit-f4");
}

/// The verdict of a held command, as `dev/stabilize-step hold-wait` keeps one
/// (`<scratch>/hold/<name>/verdict.json`): ONE line that ends with its own sha256. The step
/// suite hands that tool's own file to this script
/// (`dev_stabilize_step::the_tools_verdict_file_is_what_the_record_script_records`); here
/// the file is composed, so that every way it can be wrong is.
fn verdict_file(rig: &Rig, name: &str, body: &Value) -> PathBuf {
    let text = body.to_string();
    let line = format!(
        "{}, \"sha256\": \"{}\"}}\n",
        &text[..text.len() - 1],
        sha256_of(&text)
    );
    let path = rig.tmp.join(format!("{name}.verdict.json"));
    fs::write(&path, line).expect("write a verdict's file");
    path
}

/// What the tool keeps of a regression set that ran to its end as `verdict`.
fn regression_verdict(rig: &Rig, verdict: &str, why: Option<&str>, commit: &str) -> Value {
    let work = rig.tmp.join("scratch/hold/regression-r1-a1/work");
    json!({
        "tool": "stabilize-step", "name": "regression-r1-a1", "kind": "regression",
        "asked": {"previous": sha('e'), "candidate": commit, "list": "lists/intended-changes.tsv"},
        "exit": if verdict == "green" { 0 } else { 1 }, "seconds": 2100,
        "verdict": verdict, "why": why,
        "detail": "22 difference(s), 1 of them off the list; 11 test(s) excluded by a row",
        "facts": {"status": verdict, "previous": sha('e'), "candidate": commit,
                  "list_sha256": sha256('7'), "differences": 22, "not_on_list": 1, "excluded": 11},
        "evidence": {"line": {"tool": "regression-set", "status": verdict,
                              "previous": {"commit": sha('e'), "sha256": sha256('1')},
                              "candidate": {"commit": commit, "sha256": sha256('2')},
                              "list": {"path": "lists/intended-changes.tsv", "commit": commit,
                                       "sha256": sha256('7'), "rows": 33},
                              "excluded": [{"binary": "jigc::g_flow", "test": "flow01::a", "change": "fails on its own binary",
                                            "pointer": "excluded:records/run-2.json"}],
                              "not_on_list": [{"binary": "jigc::g_doc", "test": "doc::b \u{2014} a name"}],
                              "evidence": work.join("evidence"), "work": work}},
        "output": "hold/regression-r1-a1/output", "output_sha256": sha256('3'),
    })
}

/// **A held check that left no verdict is void, and says why in a word** (the coordinator's
/// sixth group of the pass that followed the core's review; the harness's `K11`, item 8: *the
/// record script owes a word*). A held check can end with no verdict's file to hand in — its
/// job is dead, its start was refused, the stage ended while it ran, a gate is not held
/// again off the candidate's tree — and `result-set` took a held item's result from that
/// file alone: the item got no row, stayed due, and `next` stayed `retest` for a re-run the
/// harness had to refuse. A state the stage could not leave. So `void`, and only `void`, is
/// taken as a word for a held item — with its reason in a DECLARED SHAPE, a word and
/// optionally a key (`<word>` or `<word>:<key>`): never a sentence. `green` and `red` are
/// still the tool's verdict or nothing. Such a void is void like any item's: it forbids
/// `close`, it is owed its re-run, and after two it is the human's.
#[test]
fn a_held_check_that_left_no_verdict_is_void_by_a_word_and_nothing_else_is_a_word() {
    let rig = Rig::new("held-void");
    fs::create_dir_all(rig.tmp.join("scratch/hold/regression-r1-a1/work"))
        .expect("the scratch root a stage hands its writers");
    rig.run(
        &run_set(RUN),
        &format!(r#"{{{BOUNDED}, {RELEASE}, "clauses": ["clause-a"]}}"#),
    )
    .must(OK, "the run's facts");
    let held = json!({"item": "regression-set", "kind": "held-regression", "clause": "clause-a",
                      "runs": "every-candidate",
                      "brief": "the regression set, held and judged by dev/stabilize-step"});
    rig.run(&item_set(RUN), &json!([held]).to_string())
        .must(OK, "a held check");
    rig.run(&scope_set(RUN, "1"), &scope(&[INSIDE], &[]).to_string())
        .must(OK, "round 1's scope");
    let commit = sha('a');
    let scratch = rig.tmp.join("scratch").display().to_string();
    let result = |rows: Value| {
        let mut args = result_set(RUN, "1", &commit);
        args.push(format!("--scratch={scratch}"));
        rig.run(&args, &rows.to_string())
    };
    let void =
        |reason: &str| json!([{"item": "regression-set", "outcome": "void", "reason": reason}]);

    // STILL REFUSED, each with nothing written: green and red as words; a void whose reason
    // is no word of the shape — a sentence, a path, a character outside ASCII, nothing.
    let before = rig.snapshot();
    let seen = result(json!([{"item": "regression-set", "outcome": "green"}]));
    seen.refused(BAD_VALUE, "green, as a word, for a held check");
    assert!(
        seen.stderr
            .contains("No outcome word is taken from a caller"),
        "{}",
        seen.stderr
    );
    for reason in [
        "the supervisor was killed",
        "dead: regression-r1-a1",
        "Dead",
        "dead:",
        ":regression-r1-a1",
        "dead:a/b",
        "dead:regression-r1-a1:again",
        "d\u{e9}ad",
        "-",
        &"a".repeat(201),
    ] {
        let seen = result(void(reason));
        seen.refused(BAD_VALUE, &format!("a void whose reason is {reason:?}"));
        assert!(
            seen.stderr.contains("says why in a word"),
            "{reason:?}: {}",
            seen.stderr
        );
    }
    assert_eq!(rig.snapshot(), before, "a refused result writes nothing");

    // TAKEN: void, with a word and a key.
    let seen = result(void("dead:regression-r1-a1"));
    seen.must(OK, "a held check that left no verdict");
    assert_eq!(
        seen.json()["recorded"],
        json!([{"item": "regression-set", "attempt": 1, "outcome": "void"}])
    );
    assert_eq!(
        table(&rig.read(&results_path("1")), &RESULT_COLUMNS),
        [[
            "`regression-set`",
            "1",
            format!("`{commit}`").as_str(),
            "void",
            "without a verdict: dead:regression-r1-a1"
        ]]
    );
    assert!(
        !rig.run_dir().join("r1/checks").exists(),
        "no verdict was read, and none is written on record"
    );
    rig.run(
        &round_set(RUN, "1"),
        &json!({"candidate": commit}).to_string(),
    )
    .must(OK, "the round's candidate");

    // IT IS VOID LIKE ANY ITEM'S: the clause is void, `close` is forbidden by it, and the
    // item is owed its re-run — which is taken, as a word again or as the tool's verdict.
    let read = rig.state();
    assert_eq!(
        json!([
            read["next"],
            read["forbids_close"],
            read["clauses"][0]["status"],
            read["retest"]
        ]),
        json!(["retest", [{"clause": "clause-a", "status": "void"}], "void", ["clause-a"]]),
        "{read}"
    );
    // A verdict's file planted for the attempt that left none is refused: the result says
    // there was none.
    let planted = rig.run_dir().join("r1/checks/regression-set.a1.json");
    fs::create_dir_all(planted.parent().expect("the checks directory")).expect("create checks/");
    fs::write(
        &planted,
        json!({"item": "regression-set", "attempt": 1, "round": 1, "verdict": "green"}).to_string(),
    )
    .expect("plant a verdict");
    rig.run(&state(RUN), "")
        .refused(CORRUPT, "a verdict on record for a run that left none");
    fs::remove_file(&planted).expect("take the planted verdict away");
    fs::remove_dir(planted.parent().expect("the checks directory")).expect("remove checks/");

    // MUST NOT CHANGE: the re-run's result from the tool's verdict file, as ever.
    let green = verdict_file(
        &rig,
        "green",
        &regression_verdict(&rig, "green", None, &commit),
    );
    let seen = result(json!([{"item": "regression-set", "verdict": green}]));
    seen.must(OK, "the re-run, judged by the tool");
    assert_eq!(
        seen.json()["recorded"],
        json!([{"item": "regression-set", "attempt": 2, "outcome": "green"}])
    );
    let read = rig.state();
    assert_eq!(
        json!([read["forbids_close"], read["clauses"][0]["status"]]),
        json!([[], "green"]),
        "{read}"
    );
}

/// **A scripted check's result is the tool's verdict, and no outcome word is taken from the
/// caller** (the second repair plan's `K10`; the re-review's `R-M8`). An item of a kind that
/// begins `held-` is a check whose command `dev/stabilize-step` holds and judges. Its
/// result is written from the verdict file that tool keeps — the row names the file, and
/// nothing else — and the verdict REACHES THE RECORD AS A FILE WRITTEN ONCE,
/// `r<N>/checks/<item>.a<attempt>.json`: the two commits, the list's hash and what was
/// excluded are on record, host paths replaced as in every file of a run. A row that
/// brings its own word, a file that is not that tool's line, a verdict of another kind or
/// of another commit are refused; a red verdict is filed as a finding, as every red check
/// is; the file is vetted as one; and a result whose verdict file is gone is missed.
#[test]
fn a_scripted_checks_result_is_the_tools_verdict() {
    let rig = Rig::new("held-check");
    fs::create_dir_all(rig.tmp.join("scratch/hold/regression-r1-a1/work"))
        .expect("the scratch root a stage hands its writers");
    rig.run(
        &run_set(RUN),
        &format!(r#"{{{BOUNDED}, {RELEASE}, "clauses": ["clause-a"]}}"#),
    )
    .must(OK, "the run's facts");
    let held = json!({"item": "regression-set", "kind": "held-regression", "clause": "clause-a",
                      "runs": "every-candidate",
                      "brief": "the regression set, held and judged by dev/stabilize-step"});
    let mut plain = held.clone();
    plain["item"] = json!("ci");
    plain["kind"] = json!("check");
    rig.run(&item_set(RUN), &json!([held, plain]).to_string())
        .must(OK, "a held check, and a check an agent reads");
    rig.run(&scope_set(RUN, "1"), &scope(&[INSIDE], &[]).to_string())
        .must(OK, "round 1's scope");
    let commit = sha('a');
    let scratch = rig.tmp.join("scratch").display().to_string();
    let result = |rows: Value| {
        let mut args = result_set(RUN, "1", &commit);
        args.push(format!("--scratch={scratch}"));
        rig.run(&args, &rows.to_string())
    };
    let green = verdict_file(
        &rig,
        "green",
        &regression_verdict(&rig, "green", None, &commit),
    );
    let before = rig.snapshot();

    // NO OUTCOME WORD IS TAKEN FROM THE CALLER — and a verdict file is no row of an item
    // an agent reads.
    for (what, row, says) in [
        (
            "an outcome word for a held check",
            json!({"item": "regression-set", "outcome": "green"}),
            "No outcome word is taken from a caller",
        ),
        (
            "a red, as a word — with what a red run brings",
            json!({"item": "regression-set", "outcome": "red", "doctype": "jigc-feedback",
                   "door": "jigc setup", "repro": "it was red"}),
            "No outcome word is taken from a caller",
        ),
        (
            "a void whose reason is a sentence, and no word",
            json!({"item": "regression-set", "outcome": "void", "reason": "it did not run"}),
            "says why in a word",
        ),
        (
            "a verdict's file, and a word beside it",
            json!({"item": "regression-set", "verdict": green, "outcome": "green"}),
            "and nothing else",
        ),
        (
            "a verdict's file for a check that is not held",
            json!({"item": "ci", "verdict": green}),
            "is no held check",
        ),
    ] {
        let seen = result(json!([row]));
        seen.refused(BAD_VALUE, what);
        assert!(seen.stderr.contains(says), "{what}: {}", seen.stderr);
    }
    // A file that is not the tool's verdict of THIS check, on THIS commit.
    let of = |name: &str, change: &dyn Fn(&mut Value)| {
        let mut body = regression_verdict(&rig, "green", None, &commit);
        change(&mut body);
        verdict_file(&rig, name, &body)
    };
    let retyped = rig.tmp.join("retyped.verdict.json");
    let typed = fs::read_to_string(&green).expect("the verdict");
    let again = typed.replace("\"verdict\":\"green\"", "\"verdict\": \"green\"");
    assert_ne!(again, typed, "one space more, and the same JSON");
    fs::write(&retyped, again).expect("retype the verdict");
    for (what, file) in [
        (
            "a file that is not there",
            rig.tmp.join("no-such.verdict.json"),
        ),
        ("a line that does not hold to its hash", retyped),
        (
            "another tool's line",
            of("tool", &|body| body["tool"] = json!("an-agent")),
        ),
        (
            "a verdict of another kind",
            of("kind", &|body| body["kind"] = json!("gate")),
        ),
        (
            "a word that is no verdict",
            of("word", &|body| body["verdict"] = json!("passed")),
        ),
        (
            "a verdict of another candidate",
            of("commit", &|body| {
                body["asked"]["candidate"] = json!(sha('b'))
            }),
        ),
        (
            "a void that does not say why",
            of("why", &|body| body["verdict"] = json!("void")),
        ),
    ] {
        let seen = result(json!([{"item": "regression-set", "verdict": file}]));
        seen.refused(BAD_VALUE, what);
        assert!(seen.stderr.contains("verdict"), "{what}: {}", seen.stderr);
    }
    assert_eq!(rig.snapshot(), before, "a refused verdict writes nothing");

    // THE RESULT IS THE FILE'S WORD, and the verdict is on record, written once.
    let red = verdict_file(&rig, "red", &regression_verdict(&rig, "red", None, &commit));
    let seen = result(json!([{"item": "regression-set", "verdict": red}, ran("ci", "green")]));
    seen.must(OK, "a held check's result, from its verdict file");
    assert_eq!(
        seen.json()["recorded"],
        json!([{"item": "regression-set", "attempt": 1, "outcome": "red"},
               {"item": "ci", "attempt": 1, "outcome": "green"}])
    );
    let on_record = format!("completions/artifacts/{RUN}/r1/checks/regression-set.a1.json");
    let text = rig.read(&on_record);
    let kept: Value = serde_json::from_str(&text).expect("the verdict on record is JSON");
    assert_eq!(
        json!([
            kept["item"],
            kept["attempt"],
            kept["round"],
            kept["commit"],
            kept["kind"],
            kept["verdict"]
        ]),
        json!(["regression-set", 1, 1, commit, "regression", "red"]),
        "{kept}"
    );
    assert_eq!(
        json!([
            kept["evidence"]["line"]["previous"]["commit"],
            kept["evidence"]["line"]["candidate"]["commit"],
            kept["evidence"]["line"]["list"]["sha256"],
            kept["evidence"]["line"]["excluded"][0]["test"]
        ]),
        json!([sha('e'), commit, sha256('7'), "flow01::a"]),
        "the two commits, the list's hash and what was excluded are on record: {kept}"
    );
    assert_eq!(
        kept["evidence"]["line"]["work"], "<scratch>/hold/regression-r1-a1/work",
        "a host path is its public placeholder, as in every file of a run: {kept}"
    );
    assert!(!text.contains(&rig.tmp.display().to_string()), "{text}");
    // A RED CHECK IS A FINDING, filed under the item's own key.
    assert_eq!(seen.json()["findings"], json!(["red-regression-set"]));
    let read = rig.state();
    let finding = &read["ledger"][0];
    assert_eq!(
        json!([finding["key"], finding["grade"], finding["clause"]]),
        json!(["red-regression-set", "ungraded", "clause-a"])
    );
    assert!(
        finding["repro"]
            .as_str()
            .is_some_and(|repro| repro.contains(&on_record)),
        "the finding's repro names the verdict on record: {finding}"
    );

    // THE FILE IS VETTED AS ONE: as the script wrote it, it passes; changed by a hand,
    // it is no verdict.
    let vet = |path: &str| rig.run(&strings(&["vet", &format!("--run={RUN}"), "--", path]), "");
    vet(&on_record).must(OK, "the verdict on record, as written");
    fs::write(
        rig.root.join(&on_record),
        text.replace("\"red\"", "\"green\""),
    )
    .expect("change a word");
    let seen = vet(&on_record);
    seen.must(VET_MISMATCH, "a verdict a hand turned green");
    assert_eq!(
        seen.json()["refused"][0]["why"],
        "bad-value",
        "{}",
        seen.stdout
    );
    // And the state does not read across it: the result says red, and so does its file.
    rig.run(&state(RUN), "").refused(
        CORRUPT,
        "a verdict on record that says another word than its result",
    );
    fs::write(rig.root.join(&on_record), &text).expect("the verdict again");
    rig.state();
    // WHAT IS DELETED IS MISSED.
    fs::remove_file(rig.root.join(&on_record)).expect("delete the verdict");
    let gone = rig.run(&state(RUN), "");
    gone.refused(CORRUPT, "a result whose verdict file is gone");
    assert!(
        gone.stderr.contains("regression-set.a1.json"),
        "{}",
        gone.stderr
    );
    fs::write(rig.root.join(&on_record), &text).expect("the verdict again");
    // A file beside the verdicts that has no verdict's name is no file of a run.
    let stray = format!("completions/artifacts/{RUN}/r1/checks/notes.md");
    fs::write(rig.root.join(&stray), "a note\n").expect("write a stray file");
    let seen = vet(&stray);
    seen.must(VET_MISMATCH, "a stray file beside the verdicts");
    assert_eq!(
        seen.json()["refused"][0]["why"],
        "bad-id",
        "{}",
        seen.stdout
    );
}

// ---------------------------------------------------------------------------
// 32 · A row carries what the queue is ranked by
// ---------------------------------------------------------------------------

/// What the tool keeps of a candidate's gate that ran to its end green.
fn gate_verdict(commit: &str) -> Value {
    json!({
        "tool": "stabilize-step", "name": "gate-r1-a1", "kind": "gate",
        "asked": {"commit": commit}, "exit": 0, "seconds": 1400,
        "verdict": "green", "why": null, "detail": "GATE: PASS",
        "facts": {"verdict": "pass", "failed": 0},
        "evidence": {"totals": "tests   passed=4700 failed=0  (over 15 test binaries)"},
        "output": "hold/gate-r1-a1/output", "output_sha256": sha256('4'),
    })
}

/// **One whole `test` stage, as the harness makes its calls today** — the opening's writes,
/// the attempt's marker, the scope and the reports from files, the reads an agent makes by
/// key, the report check and the vet, the record's ONE batch from a file held to its hash
/// (the report check, the candidate's gate, a result per item — a held check green, a held
/// check red, a check an agent read red, a hunt green — the findings, their triage with a
/// verdict of each kind, the round's facts, the ledger check), what is pending, the vet of
/// the commit, the settle; and then the invocation that finishes the round's triage.
/// Returns what every call printed, in order, and every file the run's directory then
/// holds: the answers and the bytes.
fn a_stage_as_the_harness_makes_its_calls(rig: &Rig) -> String {
    let scratch = rig.tmp.join("scratch");
    fs::create_dir_all(scratch.join("hold/regression-r1-a1/work"))
        .expect("the scratch root a stage hands its writers");
    let under_scratch = format!("--scratch={}", scratch.display());
    let commit = sha('a');
    let mut told = String::new();
    let mut call_ = |label: &str, mut args: Vec<String>, writes: bool, stdin: &str| -> Value {
        if writes {
            args.push(under_scratch.clone());
        }
        let seen = rig.run(&args, stdin);
        seen.must(OK, label);
        assert!(seen.stderr.is_empty(), "{label}: {}", seen.stderr);
        told.push_str(&format!("== {label}\n{}", seen.stdout));
        if seen.stdout.trim().starts_with(['{', '[']) {
            seen.json()
        } else {
            Value::Null
        }
    };
    let fed = |name: &str, text: &str| {
        let path = scratch.join(name);
        fs::write(&path, text).expect("write what an agent hands a writer");
        path
    };
    let reported = |reporter: &str, attempt: &str, says: &str| {
        let body = format!("# {reporter}\n\n{says}\n\n{ENDS}\n");
        let file = fed(&format!("{reporter}.a{attempt}.md"), &body);
        from_file(report(RUN, "1", reporter, attempt), &file)
    };
    let batch_of = |name: &str, calls: Value| {
        let text = format!("{calls}\n");
        let mut args = from_file(apply(RUN, Some("1")), &fed(name, &text));
        args.push(format!("--sha256={}", sha256_of(&text)));
        args
    };
    let within = |mut args: Vec<String>| {
        args.push(under_scratch.clone());
        args
    };

    // THE OPENING: the run's facts, a declared bound, the test set, the ledger's rows.
    call_(
        "the opening: run-set",
        run_set(RUN),
        false,
        &format!(r#"{{{BOUNDED}, {RELEASE}, "clauses": ["no-lost-files", "routes-work"]}}"#),
    );
    call_(
        "the opening: bound-set",
        bound_set(RUN, "non-jigc-writer", &BOUND),
        true,
        "",
    );
    let unit = |id: &str, kind: &str, clause: &str, runs: &str, doors: &[&str]| {
        json!({"item": id, "kind": kind, "clause": clause, "runs": runs, "doors": doors,
               "brief": format!("the brief of `{id}`, as the opening record names it")})
    };
    let items = json!([
        unit("gate", "held-gate", "no-lost-files", "every-candidate", &[]),
        unit(
            "regression-set",
            "held-regression",
            "no-lost-files",
            "every-candidate",
            &[]
        ),
        unit("ci", "check", "routes-work", "every-candidate", &[]),
        unit(
            "review-setup",
            "review-row",
            "routes-work",
            "in-scope",
            &[INSIDE]
        ),
        unit(
            "review-show",
            "review-row",
            "routes-work",
            "in-scope",
            &[EXCLUDED]
        ),
    ]);
    call_(
        "the opening: item-set",
        item_set(RUN),
        true,
        &items.to_string(),
    );
    let mut seeded = row_at("seed-hook", INSIDE);
    seeded["round"] = json!(0);
    seeded["source"] = json!("the canary's ledger, row 4");
    let mut old = row_at("seed-old", UNLISTED);
    old["round"] = json!(0);
    call_(
        "the opening: ledger-add",
        ledger_add(RUN),
        true,
        &json!([seeded, old]).to_string(),
    );
    call_("the opening: state", state(RUN), false, "");

    // THE STAGE: its attempt's marker, its scope, the reads by key, its reports.
    call_(
        "the attempt's marker",
        reported("attempt", "1", "round 1, attempt 1, begun"),
        true,
        "",
    );
    let doors = scope(&[INSIDE], &[EXCLUDED]).to_string();
    call_(
        "the scope, from a file",
        from_file(scope_set(RUN, "1"), &fed("scope.json", &doors)),
        true,
        "",
    );
    call_(
        "a read by key: item",
        read_item(RUN, "review-setup"),
        false,
        "",
    );
    call_(
        "a read by key: item-doors",
        read_doors(RUN, "1", "review-setup"),
        false,
        "",
    );
    for (reporter, says) in [
        ("preflight", "ci: red — the workflow's `lint` job failed."),
        ("review-setup", "Three findings, each with its block."),
    ] {
        call_(
            &format!("a report, from a file: {reporter}"),
            reported(reporter, "1", says),
            true,
            "",
        );
    }
    call_(
        "the reports, checked",
        check_reports(RUN, "1", "1", &["attempt", "preflight", "review-setup"]),
        false,
        "",
    );
    let pending = call_("what is pending", keeper("pending", RUN), false, "");
    let once: Vec<&str> = pending["once"]
        .as_array()
        .expect("the files written once")
        .iter()
        .map(|path| path.as_str().expect("a path"))
        .collect();
    call_(
        "the vet of what is written once",
        vet(RUN, None, &once),
        false,
        "",
    );
    call_(
        "a read by key: untriaged",
        keeper("untriaged", RUN),
        false,
        "",
    );
    for (reporter, says) in [
        ("triage-p1", "Five findings graded."),
        (
            "verify-seed-hook",
            "Confirmed; green on the previous release.",
        ),
        ("verify-review-f1", "Refuted: it does not reproduce."),
        ("verify-review-f2", "Confirmed."),
    ] {
        call_(
            &format!("a report, from a file: {reporter}"),
            reported(reporter, "1", says),
            true,
            "",
        );
    }

    // THE RECORD: one batch, from a file held to its hash.
    let launched = [
        "attempt",
        "preflight",
        "review-setup",
        "triage-p1",
        "verify-seed-hook",
        "verify-review-f1",
        "verify-review-f2",
    ];
    let green = verdict_file(rig, "gate", &gate_verdict(&commit));
    let red = verdict_file(
        rig,
        "regression",
        &regression_verdict(rig, "red", None, &commit),
    );
    let results = json!([
        {"item": "gate", "verdict": green},
        {"item": "regression-set", "verdict": red},
        {"item": "ci", "outcome": "red", "doctype": "jigc-feedback", "door": "the check `ci`",
         "repro": "the preflight's report: the workflow's `lint` job failed"},
        {"item": "review-setup", "outcome": "green"},
    ]);
    let found = json!([
        row_at("review-f1", INSIDE),
        row_at("review-f2", EXCLUDED),
        row_at("review-f3", INSIDE),
    ]);
    let triaged = json!([
        {"key": "seed-hook", "grade": "breaks", "verdict": "confirmed", "regression": true},
        {"key": "seed-old", "grade": "out-of-scope", "bound": "non-jigc-writer"},
        {"key": "review-f1", "grade": "unclear", "verdict": "refuted"},
        {"key": "review-f2", "grade": "breaks", "verdict": "confirmed"},
        {"key": "review-f3", "grade": "no-break"},
    ]);
    let summary = rig.summary("candidate", &[], &[]);
    let record = json!([
        call(check_reports(RUN, "1", "1", &launched), ""),
        call(within(gate_set(RUN, "1", &commit, &summary)), ""),
        call(within(result_set(RUN, "1", &commit)), &results.to_string()),
        call(within(ledger_add(RUN)), &found.to_string()),
        call(triage_set(RUN, "1"), &triaged.to_string()),
        call(
            round_set(RUN, "1"),
            &json!({"candidate": commit, "base": sha('b'), "binary": sha256('c')}).to_string()
        ),
        call(
            check_ledger(
                RUN,
                &[
                    "seed-hook",
                    "seed-old",
                    "review-f1",
                    "review-f2",
                    "review-f3"
                ]
            ),
            ""
        ),
    ]);
    call_(
        "the record's batch",
        batch_of("record.json", record),
        true,
        "",
    );
    let pending = call_("the batch, pending", keeper("pending", RUN), false, "");
    let batch: Vec<&str> = pending["batch"]["files"]
        .as_object()
        .expect("the batch's files")
        .keys()
        .map(String::as_str)
        .collect();
    call_(
        "the vet of the record's commit",
        vet(RUN, Some("docs(record): a record step"), &batch),
        false,
        "",
    );
    call_("the batch, settled", keeper("settle", RUN), false, "");
    call_("the state after the record", state(RUN), false, "");

    // THE INVOCATION THAT FINISHES THE ROUND'S TRIAGE: the two red runs are graded, one of
    // them verified.
    call_(
        "the second attempt's marker",
        reported("attempt", "2", "round 1, attempt 2, begun: the triage"),
        true,
        "",
    );
    call_(
        "the untriaged rows, again",
        keeper("untriaged", RUN),
        false,
        "",
    );
    for (reporter, says) in [
        ("triage-p1", "Two red runs graded."),
        (
            "verify-red-ci",
            "Confirmed; red on the previous release too.",
        ),
    ] {
        call_(
            &format!("a report of the second attempt: {reporter}"),
            reported(reporter, "2", says),
            true,
            "",
        );
    }
    let lap =
        json!([
        call(check_reports(RUN, "1", "2", &["attempt", "triage-p1", "verify-red-ci"]), ""),
        call(
            triage_set(RUN, "1"),
            &json!([
                {"key": "red-ci", "grade": "breaks", "verdict": "confirmed", "regression": false},
                {"key": "red-regression-set", "grade": "unclear"},
            ])
            .to_string()
        ),
        call(check_ledger(RUN, &["red-ci", "red-regression-set"]), ""),
    ]);
    call_(
        "the second record's batch",
        batch_of("lap.json", lap),
        true,
        "",
    );
    call_(
        "the second batch, settled",
        keeper("settle", RUN),
        false,
        "",
    );
    call_("the state at the end", state(RUN), false, "");

    // AND THE BYTES: every file the run's directory holds.
    let mut files = BTreeMap::new();
    walk(&rig.run_dir(), &rig.run_dir(), &rig.tmp, &mut files);
    for (path, holds) in files {
        if let Some(text) = holds.strip_prefix("file: ") {
            told.push_str(&format!("-- {path}\n{text}"));
        }
    }
    told
}

